@js:
var s = [];
function p(t, u, f, b){ s.push({title:t, url:u||'', style:{layout_flexGrow:f, layout_flexBasisPercent:b}}); }
function sec(t){ s.push({title:t, url:null, style:{layout_flexGrow:1, layout_flexBasisPercent:1}}); }
var config = {};
try { var raw = source.getVariable(); if (raw && raw!=='' && raw!=='null' && raw!=='undefined') config = JSON.parse(raw); } catch(e){}
var gender = config.gender || '1';
var mode = config.mode || '标签';
s.push({title:"频道", type:"select", chars:["男频","女频"], default: gender==='2'?'女频':'男频',
  action:"(function(){var c={};try{c=JSON.parse(source.getVariable()||'{}');}catch(e){}c.gender=String(infoMap['频道']||'男频').indexOf('女')>=0?'2':'1';source.setVariable(JSON.stringify(c));java.refreshExplore();})()",
  style:{layout_flexGrow:1, layout_flexBasisPercent:0.4}});
s.push({title:"板块", type:"select", chars:["标签","分类","榜单"], default: mode,
  action:"(function(){var c={};try{c=JSON.parse(source.getVariable()||'{}');}catch(e){}c.mode=infoMap['板块']||'标签';source.setVariable(JSON.stringify(c));java.refreshExplore();})()",
  style:{layout_flexGrow:1, layout_flexBasisPercent:0.4}});
if (mode==='分类') {
  sec('小说分类');
  var cats;
  if (gender==='2') { cats=[['现代言情','1'],['古代言情','2'],['幻想言情','4'],['都市言情','8'],['民国','12']]; }
  else { cats=[['玄幻','202'],['仙侠','205'],['都市','203'],['历史','56'],['科幻','64']]; }
  for (var ci=0; ci<cats.length; ci++) {
    p(cats[ci][0], 'https://api-bc.wtzw.com/category?gender=' + gender + '&category_id=' + cats[ci][1] + '&type=cat&page={{page}}', 1, 0.4);
  }
} else if (mode==='标签') {
  var groups = [];
  var groupCats = {};
  try {
    var headers = buildHeaders(java);
    var params = { gender:'0', category_id:'0', tab_type: gender, cache_ver:'' };
    signParams(params, java);
    var u = 'https://api-bc.wtzw.com/api/v5/category/index?' + urlEncode(params) + ',{"headers":' + JSON.stringify(headers) + '}';
    var cd = JSON.parse(java.ajax(u));
    var list = (cd && cd.data && cd.data.category_list) || [];
    for (var gi=0; gi<list.length; gi++) {
      var g = list[gi] || {};
      var gn = g.title || '';
      var subs = g.list || [];
      if (gn) groups.push(gn);
      var arr = groupCats[gn] || (groupCats[gn]=[]);
      var seen = {};
      for (var si=0; si<subs.length; si++) {
        var sub = subs[si] || {};
        var cid2 = sub.category_id;
        if (cid2 && !seen[cid2]) { seen[cid2]=1; arr.push({id:cid2, title:sub.title||cid2}); }
      }
    }
  } catch(e){}
  var groupOptions = groups.length ? groups : ['热门'];
  var tg = config.tgroup || '热门';
  if (groupOptions.indexOf(tg) < 0) tg = groupOptions[0];
  s.push({title:"标签组", type:"select", chars: groupOptions, default: tg,
    action:"(function(){var c={};try{c=JSON.parse(source.getVariable()||'{}');}catch(e){}c.tgroup=infoMap['标签组']||'热门';source.setVariable(JSON.stringify(c));java.refreshExplore();})()",
    style:{layout_flexGrow:1, layout_flexBasisPercent:0.4}});
  sec(tg + '标签');
  var tgArr = groupCats[tg] || [];
  for (var ti=0; ti<tgArr.length; ti++) {
    p(tgArr[ti].title, 'https://api-bc.wtzw.com/category?gender=' + gender + '&category_id=' + tgArr[ti].id + '&type=tag&page={{page}}', 1, 0.4);
  }
} else {
  sec('小说榜单');
  var ranks=[['推荐榜','rec_list'],['大热榜','hot_list'],['新书榜','new_list'],['完结榜','end_list'],['飙升榜','up_list'],['好评榜','good_comment_list'],['热搜榜','hot_search_list'],['必读榜','must_read_list'],['礼物榜','reward_value_list']];
  for (var ri=0; ri<ranks.length; ri++) {
    p(ranks[ri][0], 'https://api-bc.wtzw.com/category?gender=' + gender + '&rank_type=' + ranks[ri][1] + '&type=rank&page={{page}}', 1, 0.4);
  }
}
JSON.stringify(s);

