function urlEncode(param, key, encode) {
    if (param == null) return '';
    var s = '';
    var t = typeof param;
    if (t == 'string' || t == 'number' || t == 'boolean') {
        s += '&' + key + '=' + (encode == null || encode ? encodeURIComponent(param) : param);
    } else {
        for (var i in param) {
            var k = key == null ? i : key + (param instanceof Array ? '[' + i + ']' : '.' + i);
            s += urlEncode(param[i], k, encode);
        }
    }
    return s;
}
function signParams(params, j) {
    var sign_key = 'd3dGiJc651gSQ8w1';
    params.sign = String(j.md5Encode(
        Object.keys(params).sort().reduce(function(pre, n) {
            return pre + n + '=' + params[n];
        }, '') + sign_key
    ));
    return params;
}
function buildHeaders(j) {
    var sign_key = 'd3dGiJc651gSQ8w1';
    var headers = {
        'app-version': '80400',
        'platform': 'android',
        'reg': '0',
        'AUTHORIZATION': '',
        'application-id': 'com.****.reader',
        'net-env': '1',
        'channel': 'unknown',
        'qm-params': ''
    };
    headers.sign = String(j.md5Encode(
        Object.keys(headers).sort().reduce(function(pre, n) {
            return pre + n + '=' + headers[n];
        }, '') + sign_key
    ));
    return headers;
}


function qmDataDetail() {
  var vs = String(java.getString('$.book.attribute.extra_info_list[*].value') || '').split(/\n+/);
  var us = String(java.getString('$.book.attribute.extra_info_list[*].unit') || '').split(/\n+/);
  var ss = String(java.getString('$.book.attribute.extra_info_list[*].sub_title') || '').split(/\n+/);
  var rows = [];
  for (var i = 0; i < vs.length; i++) {
    var v = vs[i];
    if (!v || v == 'null') continue;
    rows.push('<div class="fact"><span class="off">📊</span><span class="val">' + v + (us[i] || '') + ' · ' + (ss[i] || '') + '</span></div>');
  }
  return rows.length ? ('<div class="section"><h3>数据详情</h3><div class="facts">' + rows.join('') + '</div></div>') : '';
}
function qmOtherWorks() {
  var ts = String(java.getString('$.sections[*].section_header.section_title') || '').split(/\n+/);
  var idx = -1;
  for (var i = 0; i < ts.length; i++) {
    if (ts[i] == '作者其他作品') { idx = i; i = ts.length; }
  }
  if (idx < 0) return '';
  var titles = String(java.getString('$.sections[' + idx + '].books[*].title') || '').split(/\n+/);
  var subs = String(java.getString('$.sections[' + idx + '].books[*].sub_title') || '').split(/\n+/);
  var imgs = String(java.getString('$.sections[' + idx + '].books[*].image_link') || '').split(/\n+/);
  var rows = [];
  for (var j = 0; j < titles.length; j++) {
    var t = titles[j];
    if (!t || t == 'null') continue;
    rows.push('<div class="ob"><img class="ob-img" src="' + (imgs[j] || '') + '" onerror="this.style.display=\'none\'"/><div class="ob-main"><div class="ob-t">' + t + '</div><div class="ob-s">' + (subs[j] || '') + '</div></div></div>');
  }
  return rows.length ? ('<div class="section"><h3>作者其他作品</h3>' + rows.join('') + '</div>') : '';
}

